import { Meta, StoryObj } from "@storybook/react";
import { useArgs } from "storybook/preview-api";
import { expect, fn, userEvent, within } from "storybook/test";
import { LanguageSelector, LanguageSelectorProps } from "./language-selector";
import { ContentContainer, CurrentContentPageContextProvider, CurrentContentPageContextType } from "../../..";

const meta = {
  title: "Modules/LanguageSelector",
  component: LanguageSelector,
  args: {
    locales: [
      { url: "/", title: "Svenska", locale: "sv" },
      { url: "/en", title: "English", locale: "en" },
    ],
    currentLocale: "sv",
    slugs: {
      sv: "/",
      en: "/en",
    },
    onSelectorOpen: fn(),
    onSelectorClose: fn(),
  },
  argTypes: {
    currentLocale: {
      control: "radio",
      options: ["sv", "en"],
    },
    slugs: {
      control: "object",
    },
  },
} satisfies Meta<LanguageSelectorProps & CurrentContentPageContextType & { currentLocale: string }>;

export default meta;

const LanguageSelectorStoryWrapper = (
  args: LanguageSelectorProps & CurrentContentPageContextType & { currentLocale: string },
) => {
  const [, updateArgs] = useArgs();

  const handleSelectorClose = (clickedSlug?: string) => {
    if (clickedSlug) {
      const foundLocale = Object.entries(args.slugs).find(([, slug]) => slug === clickedSlug);
      if (foundLocale) {
        updateArgs({ currentLocale: foundLocale[0] });
      }
    }
  };

  return (
    <ContentContainer>
      <div
        style={
          {
            height: "var(--component-header-initial-height)",
            backgroundColor: "var(--component-header-color-background)",
            "--text-color": "var(--component-header-color-text)",
          } as React.CSSProperties
        }
      >
        <CurrentContentPageContextProvider
          data={{
            currentLocale: args.currentLocale,
            slugs: args.slugs,
          }}
        >
          <LanguageSelector {...args} onSelectorClose={handleSelectorClose} />
        </CurrentContentPageContextProvider>
      </div>
    </ContentContainer>
  );
};

export const Primary = LanguageSelectorStoryWrapper;

export const Expanded: StoryObj<LanguageSelectorProps & CurrentContentPageContextType & { currentLocale: string }> = {
  render: LanguageSelectorStoryWrapper,
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole("button"));
    await new Promise((resolve) => setTimeout(resolve, 300));
    await expect(canvas.getByText("Svenska")).toHaveClass("bold");
  },
};
